{
  "name": "TypoGov - Advanced Typing Exam Portal",
  "description": "A professional-grade typing exam platform with dual-language support (English/Hindi), strict government evaluation logic, and backspace restrictions."
}

export enum Language {
  ENGLISH = 'English',
  HINDI_KRUTIDEV = 'Hindi (Krutidev 010)',
  HINDI_MANGAL = 'Hindi (Mangal GAIL)'
}

export enum BackspaceMode {
  NO_BACKSPACE = 'No Backspace',
  LIMITED = 'Limited Backspace',
  FULL = 'Full Backspace'
}

export interface ExamSettings {
  language: Language;
  timerMinutes: number;
  highlightEnabled: boolean;
  backspaceMode: BackspaceMode;
  showStats: boolean;
}

export interface TypingStats {
  grossWpm: number;
  netWpm: number;
  accuracy: number;
  totalStrokes: number;
  fullMistakes: number;
  halfMistakes: number;
  totalWords: number;
  timeElapsed: number; // in seconds
}

export interface MistakeDetail {
  type: 'Full' | 'Half';
  reason: string;
  expected: string;
  typed: string;
}

import { Language } from './types';

export const PASSAGES: Record<Language, string[]> = {
  [Language.ENGLISH]: [
    "The rapid advancement of technology has fundamentally altered the landscape of modern education. Digital tools have moved from being supplementary aids to becoming essential components of the learning process. Students today have access to a wealth of information at their fingertips, enabling a level of research and collaboration that was previously unimaginable. This shift requires both educators and learners to develop new sets of skills, emphasizing critical thinking and digital literacy over rote memorization.",
    "Sustainable development is the organizing principle for meeting human development goals while simultaneously sustaining the ability of natural systems to provide the natural resources and ecosystem services on which the economy and society depend. The desired result is a state of society where living conditions and resources are used to continue to meet human needs without undermining the integrity and stability of the natural system."
  ],
  [Language.HINDI_KRUTIDEV]: [
    "vk/kqfud f'k{kk iz.kkyh esa rduhdh dks c<+kok fn;k tk jgk gSA bl cnyko us f'k{kdksa vkSj f'k{kkfFkZ;ksa nksuksa ds fy, u;s volj iSnk fd;s gSaA"
  ],
  [Language.HINDI_MANGAL]: [
    "आधुनिक शिक्षा प्रणाली में तकनीकी को बढ़ावा दिया जा रहा है। इस बदलाव ने शिक्षकों और शिक्षार्थियों दोनों के लिए नये अवसर पैदा किये हैं।"
  ]
};

// Krutidev 010 Mapping (Partial Example for Demonstration)
// In a real production app, this would be a complete ASCII to KrutiDev glyph map
export const KRUTIDEV_MAP: Record<string, string> = {
  'a': 'ं', 'b': 'व', 'c': 'ब', 'd': 'क', 'e': 'म', 'f': 'त', 'g': 'ह', 'h': 'ी', 'i': 'प', 'j': 'र', 'k': 'ा', 'l': 'स', 'm': 'उ', 'n': 'न', 'o': 'व', 'p': 'च', 'q': 'फ', 'r': 'त', 's': 'ए', 't': 'ज', 'u': 'न', 'v': 'ट', 'w': 'ू', 'x': 'ग', 'y': 'ल', 'z': 'ा',
  'A': 'ी', 'B': 'य', 'C': 'इ', 'D': 'क', 'E': 'क', 'F': 'थ', 'G': 'ळ', 'H': 'भ', 'I': 'प', 'J': 'श्र', 'K': 'ज्ञ', 'L': 'स', 'M': 'श', 'N': 'ष', 'O': 'द', 'P': 'च', 'Q': 'फ', 'R': 'त', 'S': 'ए', 'T': 'ज', 'U': 'न', 'V': 'ट', 'W': 'ू', 'X': 'ग', 'Y': 'ल', 'Z': 'ा'
};

import { TypingStats, MistakeDetail } from '../types';

export const calculateMistakes = (sourceText: string, typedText: string): { 
  fullMistakes: number, 
  halfMistakes: number,
  details: MistakeDetail[] 
} => {
  const sourceWords = sourceText.split(/\s+/);
  const typedWords = typedText.trim().split(/\s+/);

  let fullMistakes = 0;
  let halfMistakes = 0;
  const details: MistakeDetail[] = [];

  // Logic for Government Exam Typing (Word-by-word comparison)
  sourceWords.forEach((sourceWord, index) => {
    const typedWord = typedWords[index];

    if (!typedWord) {
      // Omission - Full Mistake
      fullMistakes++;
      details.push({ type: 'Full', reason: 'Omission', expected: sourceWord, typed: '[Missing]' });
      return;
    }

    if (sourceWord === typedWord) {
      return; // Correct
    }

    // Check for Half Mistakes (Case, Spacing errors are handled by split/trim, so focus on near-misses)
    if (sourceWord.toLowerCase() === typedWord.toLowerCase()) {
      // Case Error - Half Mistake
      halfMistakes++;
      details.push({ type: 'Half', reason: 'Capitalization', expected: sourceWord, typed: typedWord });
    } else if (sourceWord.length === typedWord.length) {
      // Simple spelling error - potentially half, but many Govt exams treat any spelling error as Full
      // We'll follow the rule: Substitution = Full
      fullMistakes++;
      details.push({ type: 'Full', reason: 'Substitution', expected: sourceWord, typed: typedWord });
    } else {
      fullMistakes++;
      details.push({ type: 'Full', reason: 'Substitution/Extra', expected: sourceWord, typed: typedWord });
    }
  });

  // Extra words typed
  if (typedWords.length > sourceWords.length) {
    const extraCount = typedWords.length - sourceWords.length;
    fullMistakes += extraCount;
    details.push({ type: 'Full', reason: 'Addition', expected: '[End of Passage]', typed: `${extraCount} extra words` });
  }

  return { fullMistakes, halfMistakes, details };
};

export const calculateStats = (
  sourceText: string, 
  typedText: string, 
  timeInSeconds: number,
  totalStrokes: number
): TypingStats => {
  const { fullMistakes, halfMistakes } = calculateMistakes(sourceText, typedText);
  const totalMistakes = fullMistakes + (halfMistakes * 0.5);

  const timeInMinutes = timeInSeconds / 60;
  const rawWords = totalStrokes / 5;

  const grossWpm = timeInMinutes > 0 ? (rawWords / timeInMinutes) : 0;
  // Formula: Net WPM = (Total Strokes / 5 - Total Mistakes) / Time
  const netWpm = timeInMinutes > 0 ? Math.max(0, (rawWords - totalMistakes) / timeInMinutes) : 0;

  const accuracy = rawWords > 0 ? Math.max(0, ((rawWords - totalMistakes) / rawWords) * 100) : 100;

  return {
    grossWpm: Math.round(grossWpm * 100) / 100,
    netWpm: Math.round(netWpm * 100) / 100,
    accuracy: Math.round(accuracy * 100) / 100,
    totalStrokes,
    fullMistakes,
    halfMistakes,
    totalWords: Math.floor(rawWords),
    timeElapsed: timeInSeconds
  };
};

import React from 'react';
import { Language, BackspaceMode, ExamSettings } from '../types';
import { Settings, Globe, Timer, ShieldCheck, Highlighter } from 'lucide-react';

interface Props {
  settings: ExamSettings;
  setSettings: (s: ExamSettings) => void;
  disabled: boolean;
}

const SettingsPanel: React.FC<Props> = ({ settings, setSettings, disabled }) => {
  return (
    <div className="bg-white border rounded-xl shadow-sm p-6 space-y-6">
      <div className="flex items-center gap-2 border-b pb-4">
        <Settings className="w-5 h-5 text-indigo-600" />
        <h2 className="font-bold text-lg">Exam Configuration</h2>
      </div>

      {/* Language Selection */}
      <div className="space-y-2">
        <label className="flex items-center gap-2 text-sm font-medium text-gray-700">
          <Globe className="w-4 h-4" /> Language & Keyboard
        </label>
        <select
          disabled={disabled}
          value={settings.language}
          onChange={(e) => setSettings({ ...settings, language: e.target.value as Language })}
          className="w-full border rounded-lg p-2 bg-gray-50 focus:ring-2 focus:ring-indigo-500"
        >
          {Object.values(Language).map((lang) => (
            <option key={lang} value={lang}>{lang}</option>
          ))}
        </select>
      </div>

      {/* Timer Selection */}
      <div className="space-y-2">
        <label className="flex items-center gap-2 text-sm font-medium text-gray-700">
          <Timer className="w-4 h-4" /> Exam Duration
        </label>
        <div className="grid grid-cols-5 gap-2">
          {[1, 2, 5, 10, 15].map((m) => (
            <button
              key={m}
              disabled={disabled}
              onClick={() => setSettings({ ...settings, timerMinutes: m })}
              className={`py-2 text-xs font-semibold rounded-md border transition-colors ${
                settings.timerMinutes === m
                  ? 'bg-indigo-600 text-white border-indigo-600'
                  : 'bg-white text-gray-600 hover:bg-gray-50'
              }`}
            >
              {m}m
            </button>
          ))}
        </div>
      </div>

      {/* Backspace Mode */}
      <div className="space-y-2">
        <label className="flex items-center gap-2 text-sm font-medium text-gray-700">
          <ShieldCheck className="w-4 h-4" /> Backspace Restriction
        </label>
        <div className="flex flex-col gap-2">
          {Object.values(BackspaceMode).map((mode) => (
            <label key={mode} className="flex items-center gap-2 p-2 rounded-lg border cursor-pointer hover:bg-gray-50">
              <input
                disabled={disabled}
                type="radio"
                name="backspace"
                checked={settings.backspaceMode === mode}
                onChange={() => setSettings({ ...settings, backspaceMode: mode })}
                className="text-indigo-600"
              />
              <span className="text-sm">{mode}</span>
            </label>
          ))}
        </div>
      </div>

      {/* Toggles */}
      <div className="space-y-3 pt-2">
        <label className="flex items-center justify-between cursor-pointer">
          <div className="flex items-center gap-2">
            <Highlighter className="w-4 h-4 text-gray-500" />
            <span className="text-sm font-medium">Highlight Current Word</span>
          </div>
          <input
            disabled={disabled}
            type="checkbox"
            checked={settings.highlightEnabled}
            onChange={(e) => setSettings({ ...settings, highlightEnabled: e.target.checked })}
            className="w-4 h-4 text-indigo-600 rounded"
          />
        </label>

        <label className="flex items-center justify-between cursor-pointer">
          <div className="flex items-center gap-2">
            <Settings className="w-4 h-4 text-gray-500" />
            <span className="text-sm font-medium">Show Real-time Stats</span>
          </div>
          <input
            disabled={disabled}
            type="checkbox"
            checked={settings.showStats}
            onChange={(e) => setSettings({ ...settings, showStats: e.target.checked })}
            className="w-4 h-4 text-indigo-600 rounded"
          />
        </label>
      </div>
    </div>
  );
};

export default SettingsPanel;

import React from 'react';
import { TypingStats, MistakeDetail, Language } from '../types';
import { Download, RefreshCw, CheckCircle2, AlertTriangle, Info } from 'lucide-react';
import { jsPDF } from 'jspdf';

interface Props {
  stats: TypingStats;
  details: MistakeDetail[];
  language: Language;
  onRestart: () => void;
}

const ResultsDashboard: React.FC<Props> = ({ stats, details, language, onRestart }) => {
  const exportPDF = () => {
    const doc = new jsPDF();
    doc.setFontSize(22);
    doc.text('Typing Exam Result Summary', 20, 20);

    doc.setFontSize(14);
    doc.text(`Language: ${language}`, 20, 35);
    doc.text(`Net WPM: ${stats.netWpm}`, 20, 45);
    doc.text(`Gross WPM: ${stats.grossWpm}`, 20, 55);
    doc.text(`Accuracy: ${stats.accuracy}%`, 20, 65);
    doc.text(`Full Mistakes: ${stats.fullMistakes}`, 20, 75);
    doc.text(`Half Mistakes: ${stats.halfMistakes}`, 20, 85);

    doc.save('typing-result.pdf');
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-white p-6 rounded-xl shadow-sm border text-center">
          <p className="text-gray-500 text-sm font-medium uppercase tracking-wider mb-1">Net WPM</p>
          <p className="text-4xl font-bold text-indigo-600">{stats.netWpm}</p>
        </div>
        <div className="bg-white p-6 rounded-xl shadow-sm border text-center">
          <p className="text-gray-500 text-sm font-medium uppercase tracking-wider mb-1">Accuracy</p>
          <p className="text-4xl font-bold text-green-600">{stats.accuracy}%</p>
        </div>
        <div className="bg-white p-6 rounded-xl shadow-sm border text-center">
          <p className="text-gray-500 text-sm font-medium uppercase tracking-wider mb-1">Full Mistakes</p>
          <p className="text-4xl font-bold text-red-600">{stats.fullMistakes}</p>
        </div>
        <div className="bg-white p-6 rounded-xl shadow-sm border text-center">
          <p className="text-gray-500 text-sm font-medium uppercase tracking-wider mb-1">Gross WPM</p>
          <p className="text-4xl font-bold text-gray-800">{stats.grossWpm}</p>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border overflow-hidden">
        <div className="bg-gray-50 px-6 py-4 border-b flex justify-between items-center">
          <h3 className="font-bold text-lg flex items-center gap-2">
            <Info className="w-5 h-5 text-gray-500" /> Mistake Breakdown
          </h3>
          <div className="flex gap-2">
            <button
              onClick={exportPDF}
              className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors text-sm font-medium"
            >
              <Download className="w-4 h-4" /> Download PDF
            </button>
            <button
              onClick={onRestart}
              className="flex items-center gap-2 px-4 py-2 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors text-sm font-medium"
            >
              <RefreshCw className="w-4 h-4" /> New Test
            </button>
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-gray-50 text-xs font-semibold text-gray-500 uppercase">
              <tr>
                <th className="px-6 py-3">Type</th>
                <th className="px-6 py-3">Reason</th>
                <th className="px-6 py-3">Expected</th>
                <th className="px-6 py-3">Typed</th>
              </tr>
            </thead>
            <tbody className="divide-y text-sm">
              {details.length === 0 ? (
                <tr>
                  <td colSpan={4} className="px-6 py-8 text-center text-gray-500 italic">
                    Perfect run! No mistakes detected.
                  </td>
                </tr>
              ) : (
                details.map((m, i) => (
                  <tr key={i} className="hover:bg-gray-50">
                    <td className="px-6 py-4">
                      <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium ${
                        m.type === 'Full' ? 'bg-red-100 text-red-800' : 'bg-yellow-100 text-yellow-800'
                      }`}>
                        {m.type}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-gray-600">{m.reason}</td>
                    <td className="px-6 py-4 font-mono text-gray-400">{m.expected}</td>
                    <td className="px-6 py-4 font-mono text-red-600">{m.typed}</td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default ResultsDashboard;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  Language, 
  BackspaceMode, 
  ExamSettings, 
  TypingStats, 
  MistakeDetail 
} from './types';
import { PASSAGES, KRUTIDEV_MAP } from './constants';
import { calculateStats, calculateMistakes } from './utils/calculations';
import SettingsPanel from './components/SettingsPanel';
import ResultsDashboard from './components/ResultsDashboard';
import { Keyboard, Play, Pause, RotateCcw, Layout, Clock, Activity, AlertCircle } from 'lucide-react';

const App: React.FC = () => {
  // State
  const [settings, setSettings] = useState<ExamSettings>({
    language: Language.ENGLISH,
    timerMinutes: 5,
    highlightEnabled: true,
    backspaceMode: BackspaceMode.FULL,
    showStats: true,
  });

  const [passage, setPassage] = useState('');
  const [typedText, setTypedText] = useState('');
  const [isActive, setIsActive] = useState(false);
  const [timeLeft, setTimeLeft] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const [totalStrokes, setTotalStrokes] = useState(0);
  const [stats, setStats] = useState<TypingStats | null>(null);
  const [mistakeDetails, setMistakeDetails] = useState<MistakeDetail[]>([]);

  // Refs
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const timerRef = useRef<NodeJS.Timeout | null>(null);

  // Initialize Exam
  useEffect(() => {
    const langPassages = PASSAGES[settings.language];
    setPassage(langPassages[Math.floor(Math.random() * langPassages.length)]);
    setTimeLeft(settings.timerMinutes * 60);
    resetExam();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [settings.language, settings.timerMinutes]);

  const resetExam = () => {
    setIsActive(false);
    setIsFinished(false);
    setTypedText('');
    setTotalStrokes(0);
    setStats(null);
    setMistakeDetails([]);
    setTimeLeft(settings.timerMinutes * 60);
    if (timerRef.current) clearInterval(timerRef.current);
  };

  const finishExam = useCallback(() => {
    setIsActive(false);
    setIsFinished(true);
    if (timerRef.current) clearInterval(timerRef.current);

    const finalStats = calculateStats(
      passage,
      typedText,
      settings.timerMinutes * 60 - timeLeft,
      totalStrokes
    );
    const { details } = calculateMistakes(passage, typedText);

    setStats(finalStats);
    setMistakeDetails(details);
  }, [passage, typedText, timeLeft, totalStrokes, settings.timerMinutes]);

  // Timer Logic
  useEffect(() => {
    if (isActive && timeLeft > 0) {
      timerRef.current = setInterval(() => {
        setTimeLeft((prev) => prev - 1);
      }, 1000);
    } else if (timeLeft === 0 && isActive) {
      finishExam();
    }
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [isActive, timeLeft, finishExam]);

  // Handle Input
  const handleInputChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    if (isFinished) return;
    if (!isActive) setIsActive(true);

    let val = e.target.value;

    // Krutidev Mapping Logic
    if (settings.language === Language.HINDI_KRUTIDEV) {
      const lastChar = val.slice(-1);
      if (KRUTIDEV_MAP[lastChar]) {
        val = val.slice(0, -1) + KRUTIDEV_MAP[lastChar];
      }
    }

    setTypedText(val);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    // Security: Disable Ctrl+C, Ctrl+V, Ctrl+A (optional)
    if (e.ctrlKey && (e.key === 'c' || e.key === 'v' || e.key === 'x')) {
      e.preventDefault();
      return;
    }

    // Backspace Logic
    if (e.key === 'Backspace') {
      if (settings.backspaceMode === BackspaceMode.NO_BACKSPACE) {
        e.preventDefault();
        return;
      }
      if (settings.backspaceMode === BackspaceMode.LIMITED) {
        // Only allow backspace for the current word
        const words = typedText.split(/\s+/);
        const lastWord = words[words.length - 1];
        if (lastWord === '' && typedText.endsWith(' ')) {
          e.preventDefault();
          return;
        }
      }
    }

    // Track Strokes
    if (e.key.length === 1 || e.key === 'Enter' || e.key === ' ') {
      setTotalStrokes((prev) => prev + 1);
    }
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  // Rendering passage with highlights
  const renderPassage = () => {
    const sourceWords = passage.split(/\s+/);
    const typedWords = typedText.trim().split(/\s+/);
    const currentWordIndex = typedWords.length - 1;

    return (
      <div 
        className={`text-xl leading-relaxed p-6 h-64 overflow-y-auto no-select ${
          settings.language === Language.HINDI_KRUTIDEV ? 'font-krutidev' : 
          settings.language === Language.HINDI_MANGAL ? 'font-mangal' : ''
        }`}
      >
        {sourceWords.map((word, idx) => {
          let className = "mx-1 inline-block transition-colors ";

          if (settings.highlightEnabled && idx === currentWordIndex && isActive) {
            className += "current-word px-1 rounded ";
          }

          if (idx < currentWordIndex) {
            className += typedWords[idx] === word ? "correct-word " : "incorrect-word ";
          }

          return <span key={idx} className={className}>{word}</span>;
        })}
      </div>
    );
  };

  return (
    <div className="min-h-screen pb-20">
      {/* Header */}
      <header className="bg-white border-b sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-indigo-600 p-2 rounded-lg">
              <Keyboard className="text-white w-6 h-6" />
            </div>
            <div>
              <h1 className="text-xl font-bold tracking-tight text-gray-900">TypoGov</h1>
              <p className="text-[10px] text-indigo-600 font-bold uppercase">Advanced Exam Portal</p>
            </div>
          </div>

          <div className="flex items-center gap-6">
            <div className="flex items-center gap-2 px-4 py-2 bg-gray-50 rounded-full border">
              <Clock className="w-4 h-4 text-indigo-600" />
              <span className="font-mono font-bold text-lg">{formatTime(timeLeft)}</span>
            </div>

            {!isFinished && (
              <div className="flex gap-2">
                <button
                  onClick={() => setIsActive(!isActive)}
                  className={`flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-all ${
                    isActive 
                      ? 'bg-amber-50 text-amber-600 hover:bg-amber-100' 
                      : 'bg-green-600 text-white hover:bg-green-700 shadow-md shadow-green-200'
                  }`}
                >
                  {isActive ? <><Pause className="w-4 h-4" /> Pause</> : <><Play className="w-4 h-4" /> Start</>}
                </button>
                <button
                  onClick={resetExam}
                  className="p-2 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-lg transition-colors"
                >
                  <RotateCcw className="w-5 h-5" />
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 mt-8">
        {!isFinished ? (
          <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
            {/* Left Column: Settings */}
            <div className="lg:col-span-1">
              <SettingsPanel 
                settings={settings} 
                setSettings={setSettings} 
                disabled={isActive} 
              />

              {settings.showStats && (
                <div className="mt-6 bg-white border rounded-xl p-4 shadow-sm animate-in slide-in-from-left-4 duration-500">
                  <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                    <Activity className="w-4 h-4" /> Live Performance
                  </h3>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="p-3 bg-gray-50 rounded-lg">
                      <p className="text-[10px] text-gray-500 font-bold uppercase">Strokes</p>
                      <p className="text-xl font-bold">{totalStrokes}</p>
                    </div>
                    <div className="p-3 bg-gray-50 rounded-lg">
                      <p className="text-[10px] text-gray-500 font-bold uppercase">Words</p>
                      <p className="text-xl font-bold">{Math.floor(totalStrokes / 5)}</p>
                    </div>
                  </div>
                </div>
              )}
            </div>

            {/* Right Column: Exam Area */}
            <div className="lg:col-span-3 space-y-6">
              {/* Passage Pane */}
              <div className="bg-white border rounded-2xl shadow-sm overflow-hidden flex flex-col">
