import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  Language, 
  BackspaceMode, 
  ExamSettings, 
  TypingStats, 
  MistakeDetail 
} from './types';
import { PASSAGES, KRUTIDEV_MAP } from './constants';
import { calculateStats, calculateMistakes } from './utils/calculations';
import SettingsPanel from './components/SettingsPanel';
import ResultsDashboard from './components/ResultsDashboard';
import { Keyboard, Play, Pause, RotateCcw, Layout, Clock, Activity, AlertCircle } from 'lucide-react';

const App: React.FC = () => {
  // State
  const [settings, setSettings] = useState<ExamSettings>({
    language: Language.ENGLISH,
    timerMinutes: 5,
    highlightEnabled: true,
    backspaceMode: BackspaceMode.FULL,
    showStats: true,
  });

  const [passage, setPassage] = useState('');
  const [typedText, setTypedText] = useState('');
  const [isActive, setIsActive] = useState(false);
  const [timeLeft, setTimeLeft] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const [totalStrokes, setTotalStrokes] = useState(0);
  const [stats, setStats] = useState<TypingStats | null>(null);
  const [mistakeDetails, setMistakeDetails] = useState<MistakeDetail[]>([]);

  // Refs
  const inputRef = useRef<HTMLTextAreaElement>(null);
  // Using number for browser timer reference instead of NodeJS.Timeout
  const timerRef = useRef<number | null>(null);

  // Initialize Exam
  useEffect(() => {
    const langPassages = PASSAGES[settings.language];
    setPassage(langPassages[Math.floor(Math.random() * langPassages.length)]);
    setTimeLeft(settings.timerMinutes * 60);
    resetExam();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [settings.language, settings.timerMinutes]);

  const resetExam = () => {
    setIsActive(false);
    setIsFinished(false);
    setTypedText('');
    setTotalStrokes(0);
    setStats(null);
    setMistakeDetails([]);
    setTimeLeft(settings.timerMinutes * 60);
    if (timerRef.current) clearInterval(timerRef.current);
  };

  const finishExam = useCallback(() => {
    setIsActive(false);
    setIsFinished(true);
    if (timerRef.current) clearInterval(timerRef.current);

    const finalStats = calculateStats(
      passage,
      typedText,
      settings.timerMinutes * 60 - timeLeft,
      totalStrokes
    );
    const { details } = calculateMistakes(passage, typedText);

    setStats(finalStats);
    setMistakeDetails(details);
  }, [passage, typedText, timeLeft, totalStrokes, settings.timerMinutes]);

  // Timer Logic
  useEffect(() => {
    if (isActive && timeLeft > 0) {
      // Use window.setInterval to ensure we get a number back in browser environments and avoid NodeJS namespace issues
      timerRef.current = window.setInterval(() => {
        setTimeLeft((prev) => prev - 1);
      }, 1000);
    } else if (timeLeft === 0 && isActive) {
      finishExam();
    }
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [isActive, timeLeft, finishExam]);

  // Handle Input
  const handleInputChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    if (isFinished) return;
    if (!isActive) setIsActive(true);

    let val = e.target.value;

    // Krutidev Mapping Logic
    if (settings.language === Language.HINDI_KRUTIDEV) {
      const lastChar = val.slice(-1);
      if (KRUTIDEV_MAP[lastChar]) {
        val = val.slice(0, -1) + KRUTIDEV_MAP[lastChar];
      }
    }

    setTypedText(val);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    // Security: Disable Ctrl+C, Ctrl+V, Ctrl+A (optional)
    if (e.ctrlKey && (e.key === 'c' || e.key === 'v' || e.key === 'x')) {
      e.preventDefault();
      return;
    }

    // Backspace Logic
    if (e.key === 'Backspace') {
      if (settings.backspaceMode === BackspaceMode.NO_BACKSPACE) {
        e.preventDefault();
        return;
      }
      if (settings.backspaceMode === BackspaceMode.LIMITED) {
        // Only allow backspace for the current word
        const words = typedText.split(/\s+/);
        const lastWord = words[words.length - 1];
        if (lastWord === '' && typedText.endsWith(' ')) {
          e.preventDefault();
          return;
        }
      }
    }

    // Track Strokes
    if (e.key.length === 1 || e.key === 'Enter' || e.key === ' ') {
      setTotalStrokes((prev) => prev + 1);
    }
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  // Rendering passage with highlights
  const renderPassage = () => {
    const sourceWords = passage.split(/\s+/);
    const typedWords = typedText.trim().split(/\s+/);
    const currentWordIndex = typedWords.length - 1;

    return (
      <div 
        className={`text-xl leading-relaxed p-6 h-64 overflow-y-auto no-select ${
          settings.language === Language.HINDI_KRUTIDEV ? 'font-krutidev' : 
          settings.language === Language.HINDI_MANGAL ? 'font-mangal' : ''
        }`}
      >
        {sourceWords.map((word, idx) => {
          let className = "mx-1 inline-block transition-colors ";

          if (settings.highlightEnabled && idx === currentWordIndex && isActive) {
            className += "current-word px-1 rounded ";
          }

          if (idx < currentWordIndex) {
            className += typedWords[idx] === word ? "correct-word " : "incorrect-word ";
          }

          return <span key={idx} className={className}>{word}</span>;
        })}
      </div>
    );
  };

  return (
    <div className="min-h-screen pb-20">
      {/* Header */}
      <header className="bg-white border-b sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-indigo-600 p-2 rounded-lg">
              <Keyboard className="text-white w-6 h-6" />
            </div>
            <div>
              <h1 className="text-xl font-bold tracking-tight text-gray-900">TypoGov</h1>
              <p className="text-[10px] text-indigo-600 font-bold uppercase">Advanced Exam Portal</p>
            </div>
          </div>

          <div className="flex items-center gap-6">
            <div className="flex items-center gap-2 px-4 py-2 bg-gray-50 rounded-full border">
              <Clock className="w-4 h-4 text-indigo-600" />
              <span className="font-mono font-bold text-lg">{formatTime(timeLeft)}</span>
            </div>

            {!isFinished && (
              <div className="flex gap-2">
                <button
                  onClick={() => setIsActive(!isActive)}
                  className={`flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-all ${
                    isActive 
                      ? 'bg-amber-50 text-amber-600 hover:bg-amber-100' 
                      : 'bg-green-600 text-white hover:bg-green-700 shadow-md shadow-green-200'
                  }`}
                >
                  {isActive ? <><Pause className="w-4 h-4" /> Pause</> : <><Play className="w-4 h-4" /> Start</>}
                </button>
                <button
                  onClick={resetExam}
                  className="p-2 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-lg transition-colors"
                >
                  <RotateCcw className="w-5 h-5" />
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 mt-8">
        {!isFinished ? (
          <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
            {/* Left Column: Settings */}
            <div className="lg:col-span-1">
              <SettingsPanel 
                settings={settings} 
                setSettings={setSettings} 
                disabled={isActive} 
              />

              {settings.showStats && (
                <div className="mt-6 bg-white border rounded-xl p-4 shadow-sm animate-in slide-in-from-left-4 duration-500">
                  <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                    <Activity className="w-4 h-4" /> Live Performance
                  </h3>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="p-3 bg-gray-50 rounded-lg">
                      <p className="text-[10px] text-gray-500 font-bold uppercase">Strokes</p>
                      <p className="text-xl font-bold">{totalStrokes}</p>
                    </div>
                    <div className="p-3 bg-gray-50 rounded-lg">
                      <p className="text-[10px] text-gray-500 font-bold uppercase">Words</p>
                      <p className="text-xl font-bold">{Math.floor(totalStrokes / 5)}</p>
                    </div>
                  </div>
                </div>
              )}
            </div>

            {/* Right Column: Exam Area */}
            <div className="lg:col-span-3 space-y-6">
              {/* Passage Pane */}
              <div className="bg-white border rounded-2xl shadow-sm overflow-hidden flex flex-col">
                <div className="bg-gray-50 px-6 py-3 border-b flex items-center justify-between">
                  <span className="text-xs font-bold text-gray-500 uppercase flex items-center gap-2">
                    <Layout className="w-4 h-4" /> Source Passage
                  </span>
                  <div className="flex gap-2">
                    <span className="px-2 py-0.5 bg-indigo-100 text-indigo-700 rounded text-[10px] font-bold">
                      {settings.language}
                    </span>
                  </div>
                </div>
                {renderPassage()}
              </div>

              {/* Typing Pane */}
              <div className="relative">
                <textarea
                  ref={inputRef}
                  disabled={!isActive && !isFinished}
                  value={typedText}
                  onChange={handleInputChange}
                  onKeyDown={handleKeyDown}
                  onContextMenu={(e) => e.preventDefault()}
                  placeholder={isActive ? "Start typing here..." : "Click 'Start' or begin typing to begin the exam."}
                  className={`w-full h-64 p-6 text-xl rounded-2xl border-2 focus:border-indigo-500 focus:ring-0 transition-all outline-none resize-none shadow-sm ${
                    !isActive ? 'bg-gray-50 opacity-50 select-none' : 'bg-white'
                  } ${
                    settings.language === Language.HINDI_KRUTIDEV ? 'font-krutidev' : 
                    settings.language === Language.HINDI_MANGAL ? 'font-mangal' : ''
                  }`}
                  spellCheck={false}
                  autoComplete="off"
                  autoCorrect="off"
                  autoCapitalize="off"
                />

                {!isActive && !isFinished && (
                  <div className="absolute inset-0 flex items-center justify-center bg-white/40 backdrop-blur-[2px] rounded-2xl">
                     <button 
                        onClick={() => { setIsActive(true); inputRef.current?.focus(); }}
                        className="bg-indigo-600 text-white px-8 py-3 rounded-xl font-bold shadow-xl shadow-indigo-200 hover:bg-indigo-700 transition-all transform hover:scale-105 active:scale-95"
                     >
                        Enter Exam Mode
                     </button>
                  </div>
                )}
              </div>

              {/* Help Box */}
              <div className="bg-blue-50 border border-blue-100 p-4 rounded-xl flex items-start gap-3">
                <AlertCircle className="w-5 h-5 text-blue-500 mt-0.5" />
                <div className="text-sm text-blue-800">
                  <p className="font-bold mb-1">Important Instructions:</p>
                  <ul className="list-disc list-inside space-y-1 opacity-90">
                    <li>Copy-paste is strictly disabled within the typing area.</li>
                    <li>Calculation Logic: 1 Word = 5 Strokes (including spaces).</li>
                    <li>Net WPM = ((Total Strokes / 5) - Mistakes) / Time.</li>
                    <li>Ensure you follow the {settings.backspaceMode} rule active for this session.</li>
                  </ul>
                </div>
              </div>

              <div className="flex justify-end">
                <button
                  onClick={finishExam}
                  disabled={!isActive}
                  className="bg-gray-900 text-white px-10 py-4 rounded-xl font-bold shadow-lg hover:bg-black transition-all disabled:opacity-50"
                >
                  Submit Exam
                </button>
              </div>
            </div>
          </div>
        ) : (
          stats && (
            <ResultsDashboard 
              stats={stats} 
              details={mistakeDetails} 
              language={settings.language} 
              onRestart={resetExam} 
            />
          )
        )}
      </main>

      {/* Footer Branding */}
      <footer className="mt-20 border-t py-8 text-center text-gray-400 text-sm">
        <p>© 2024 TypoGov Professional Examination Services</p>
        <p className="mt-1">ISO 9001:2015 Certified Typing Evaluation Engine</p>
      </footer>
    </div>
  );
};

