import React, { useState } from 'react';
import { TypingStats, MistakeDetail, Language } from '../types';
import { Download, RefreshCw, Info, FileSearch, Table } from 'lucide-react';
import { jsPDF } from 'jspdf';

interface Props {
  stats: TypingStats;
  details: MistakeDetail[];
  language: Language;
  sourceText: string;
  typedText: string;
  onRestart: () => void;
}

const ResultsDashboard: React.FC<Props> = ({ stats, details, language, sourceText, typedText, onRestart }) => {
  const [view, setView] = useState<'table' | 'compare'>('table');

  const exportPDF = () => {
    const doc = new jsPDF();
    doc.setFontSize(22);
    doc.text('Typing Exam Result Summary', 20, 20);

    doc.setFontSize(14);
    doc.text(`Language: ${language}`, 20, 35);
    doc.text(`Net WPM: ${stats.netWpm}`, 20, 45);
    doc.text(`Gross WPM: ${stats.grossWpm}`, 20, 55);
    doc.text(`Accuracy: ${stats.accuracy}%`, 20, 65);
    doc.text(`Full Mistakes: ${stats.fullMistakes}`, 20, 75);
    doc.text(`Half Mistakes: ${stats.halfMistakes}`, 20, 85);
    doc.text(`Total Strokes: ${stats.totalStrokes}`, 20, 95);

    doc.save('typing-result.pdf');
  };

  const sourceWords = sourceText.split(/\s+/);
  const typedWords = typedText.trim().split(/\s+/);

