import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  Language, 
  BackspaceMode, 
  ExamSettings, 
  TypingStats, 
  MistakeDetail 
} from './types';
import { PASSAGES, KRUTIDEV_MAP } from './constants';
import { calculateStats, calculateMistakes } from './utils/calculations';
import SettingsPanel from './components/SettingsPanel';
import ResultsDashboard from './components/ResultsDashboard';
import { Keyboard, Play, Pause, RotateCcw, Layout, Clock, Activity, AlertCircle } from 'lucide-react';

const App: React.FC = () => {
  // State
  const [settings, setSettings] = useState<ExamSettings>({
    language: Language.ENGLISH,
    timerMinutes: 5,
    highlightEnabled: false,
    backspaceMode: BackspaceMode.FULL,
    showStats: true,
    useCustomPassage: false,
    customPassage: "",
  });

  const [passage, setPassage] = useState('');
  const [typedText, setTypedText] = useState('');
  const [isActive, setIsActive] = useState(false);
  const [timeLeft, setTimeLeft] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const [totalStrokes, setTotalStrokes] = useState(0);
  const [stats, setStats] = useState<TypingStats | null>(null);
  const [mistakeDetails, setMistakeDetails] = useState<MistakeDetail[]>([]);

  // Refs
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const timerRef = useRef<number | null>(null);

  // Initialize Exam
  useEffect(() => {
    let finalPassage = "";
    if (settings.useCustomPassage && settings.customPassage.trim()) {
      finalPassage = settings.customPassage.trim();
    } else {
      const langPassages = PASSAGES[settings.language];
      finalPassage = langPassages[Math.floor(Math.random() * langPassages.length)];
    }

    setPassage(finalPassage);
    setTimeLeft(settings.timerMinutes * 60);
    resetExam();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [settings.language, settings.timerMinutes, settings.useCustomPassage, settings.customPassage]);

  const resetExam = () => {
    setIsActive(false);
    setIsFinished(false);
    setTypedText('');
    setTotalStrokes(0);
    setStats(null);
    setMistakeDetails([]);
    setTimeLeft(settings.timerMinutes * 60);
    if (timerRef.current) clearInterval(timerRef.current);
  };

  const finishExam = useCallback(() => {
    setIsActive(false);
    setIsFinished(true);
    if (timerRef.current) clearInterval(timerRef.current);

    const timeUsed = settings.timerMinutes * 60 - timeLeft;
    const finalStats = calculateStats(
      passage,
      typedText,
      timeUsed > 0 ? timeUsed : 1, // Avoid div by zero
      totalStrokes
    );
    const { details } = calculateMistakes(passage, typedText);

    setStats(finalStats);
    setMistakeDetails(details);
  }, [passage, typedText, timeLeft, totalStrokes, settings.timerMinutes]);

  // Timer Logic
  useEffect(() => {
    if (isActive && timeLeft > 0) {
      timerRef.current = window.setInterval(() => {
        setTimeLeft((prev) => prev - 1);
      }, 1000);
    } else if (timeLeft === 0 && isActive) {
      finishExam();
    }
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [isActive, timeLeft, finishExam]);

  // Handle Input
  const handleInputChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    if (isFinished) return;
    if (!isActive) setIsActive(true);

    let val = e.target.value;

    // Krutidev Mapping Logic
    if (settings.language === Language.HINDI_KRUTIDEV) {
      const lastChar = val.slice(-1);
      if (KRUTIDEV_MAP[lastChar]) {
        val = val.slice(0, -1) + KRUTIDEV_MAP[lastChar];
      }
    }

    setTypedText(val);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    // Security
    if (e.ctrlKey && (e.key === 'c' || e.key === 'v' || e.key === 'x')) {
      e.preventDefault();
      return;
    }

    // Backspace Logic
    if (e.key === 'Backspace') {
      if (settings.backspaceMode === BackspaceMode.NO_BACKSPACE) {
        e.preventDefault();
        return;
      }
      if (settings.backspaceMode === BackspaceMode.LIMITED) {
        const lastSpaceIndex = typedText.lastIndexOf(' ');
        if (typedText.length <= lastSpaceIndex + 1 && typedText.length > 0) {
          e.preventDefault();
          return;
        }
      }
    }

    // Track Strokes
    if (e.key.length === 1 || e.key === 'Enter' || e.key === ' ') {
      setTotalStrokes((prev) => prev + 1);
    }
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  // Rendering passage with highlights
  const renderPassage = () => {
    const sourceWords = passage.split(/\s+/);
    const typedWords = typedText.trim().split(/\s+/);
    const currentWordIndex = typedWords.length - 1;

    return (
      <div 
        className={`text-xl leading-relaxed p-6 h-64 overflow-y-auto no-select ${
          settings.language === Language.HINDI_KRUTIDEV ? 'font-krutidev' : 
          settings.language === Language.HINDI_MANGAL ? 'font-mangal' : ''
        }`}
      >
        {sourceWords.map((word, idx) => {
          let className = "mx-1 inline-block transition-colors ";

          // Only show highlight if enabled
          if (settings.highlightEnabled) {
            if (idx === currentWordIndex && isActive) {
              className += "current-word px-1 rounded ";
            }
            if (idx < currentWordIndex) {
              className += typedWords[idx] === word ? "correct-word " : "incorrect-word ";
            }
          }

          return <span key={idx} className={className}>{word}</span>;
        })}
      </div>
    );
  };

  return (
    <div className="min-h-screen pb-20 bg-gray-50">
      {/* Header */}
      <header className="bg-white border-b sticky top-0 z-50 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-indigo-600 p-2 rounded-lg shadow-indigo-200 shadow-lg">
              <Keyboard className="text-white w-6 h-6" />
            </div>
            <div>
              <h1 className="text-xl font-bold tracking-tight text-gray-900 leading-none">TypoGov</h1>
              <p className="text-[10px] text-indigo-600 font-bold uppercase mt-1">Official Examination Portal</p>
            </div>
          </div>

          <div className="flex items-center gap-6">
            <div className={`flex items-center gap-2 px-4 py-2 rounded-full border transition-all ${timeLeft < 30 ? 'bg-red-50 border-red-200 text-red-600 animate-pulse' : 'bg-white'}`}>
              <Clock className="w-4 h-4" />
              <span className="font-mono font-bold text-lg">{formatTime(timeLeft)}</span>
            </div>

            {!isFinished && (
              <div className="flex gap-2">
                <button
                  onClick={() => setIsActive(!isActive)}
                  className={`flex items-center gap-2 px-6 py-2 rounded-lg font-bold transition-all ${
                    isActive 
                      ? 'bg-amber-100 text-amber-700 hover:bg-amber-200' 
                      : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-lg shadow-indigo-100'
                  }`}
                >
                  {isActive ? <><Pause className="w-4 h-4" /> Pause</> : <><Play className="w-4 h-4" /> Start Test</>}
                </button>
                <button
                  onClick={resetExam}
                  className="p-2 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-lg transition-colors border bg-white"
                >
                  <RotateCcw className="w-5 h-5" />
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 mt-8">
        {!isFinished ? (
          <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
            <div className="lg:col-span-1">
              <SettingsPanel 
                settings={settings} 
                setSettings={setSettings} 
                disabled={isActive} 
              />

              {settings.showStats && (
                <div className="mt-6 bg-white border rounded-xl p-6 shadow-sm">
                  <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                    <Activity className="w-4 h-4" /> Live Stats
                  </h3>
                  <div className="space-y-4">
                    <div className="flex justify-between items-end">
                      <span className="text-sm text-gray-500">Strokes</span>
                      <span className="text-2xl font-bold font-mono">{totalStrokes}</span>
                    </div>
                    <div className="w-full bg-gray-100 h-2 rounded-full overflow-hidden">
                       <div className="bg-indigo-500 h-full transition-all duration-300" style={{ width: `${Math.min(100, (totalStrokes/500)*100)}%` }} />
                    </div>
                    <div className="flex justify-between items-end pt-2 border-t">
                      <span className="text-sm text-gray-500">Words (Avg)</span>
                      <span className="text-2xl font-bold font-mono">{Math.floor(totalStrokes / 5)}</span>
                    </div>
                  </div>
                </div>
              )}
            </div>

            <div className="lg:col-span-3 space-y-6">
              <div className="bg-white border-2 border-indigo-50 rounded-2xl shadow-sm overflow-hidden flex flex-col">
                <div className="bg-indigo-50/50 px-6 py-3 border-b flex items-center justify-between">
                  <span className="text-xs font-bold text-indigo-700 uppercase flex items-center gap-2 tracking-widest">
                    <Layout className="w-4 h-4" /> Source Document
                  </span>
                  {!settings.highlightEnabled && (
                    <span className="px-2 py-0.5 bg-gray-200 text-gray-600 rounded text-[10px] font-bold uppercase">
                      Strict Mode: No Highlighting
                    </span>
                  )}
                </div>
                {renderPassage()}
              </div>

              <div className="relative group">
                <textarea
                  ref={inputRef}
                  disabled={!isActive && !isFinished}
                  value={typedText}
                  onChange={handleInputChange}
                  onKeyDown={handleKeyDown}
                  onContextMenu={(e) => e.preventDefault()}
                  placeholder={isActive ? "Begin typing the passage above..." : "Press 'Start Test' to activate the typing area."}
                  className={`w-full h-64 p-8 text-xl rounded-2xl border-2 focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100 transition-all outline-none resize-none shadow-sm ${
                    !isActive ? 'bg-gray-50 opacity-60 cursor-not-allowed' : 'bg-white'
                  } ${
                    settings.language === Language.HINDI_KRUTIDEV ? 'font-krutidev' : 
                    settings.language === Language.HINDI_MANGAL ? 'font-mangal' : ''
                  }`}
                  spellCheck={false}
                  autoComplete="off"
                  autoCorrect="off"
                  autoCapitalize="off"
                />
                {!isActive && !isFinished && (
                  <div className="absolute inset-0 flex items-center justify-center bg-gray-50/40 backdrop-blur-[1px] rounded-2xl">
                     <button 
                        onClick={() => { setIsActive(true); inputRef.current?.focus(); }}
                        className="bg-white text-indigo-600 border border-indigo-100 px-8 py-4 rounded-2xl font-bold shadow-xl hover:shadow-2xl transition-all transform hover:-translate-y-1 active:translate-y-0"
                     >
                        Click to Start Typing
                     </button>
                  </div>
                )}
              </div>

              <div className="flex items-start gap-4 p-5 bg-white border border-indigo-100 rounded-2xl shadow-sm">
                <div className="p-2 bg-indigo-50 rounded-lg">
                  <AlertCircle className="w-6 h-6 text-indigo-500" />
                </div>
                <div>
                  <h4 className="font-bold text-gray-900 text-sm">Exam Information</h4>
                  <p className="text-xs text-gray-500 mt-1 leading-relaxed">
                    Calculation Rule: <span className="font-bold text-indigo-600">Net WPM = ((Total Strokes / 5) - Total Mistakes) / Time</span>. 
                    Full Mistakes are counted for omissions or substitutions. Space or capitalization errors are half-mistakes.
                    Backspace is currently <span className="font-bold uppercase">{settings.backspaceMode}</span>.
                  </p>
                </div>
              </div>

              <div className="flex justify-end gap-4">
                <button
                  onClick={finishExam}
                  disabled={!isActive}
                  className="bg-gray-900 text-white px-12 py-4 rounded-2xl font-bold shadow-xl hover:bg-black transition-all transform hover:scale-[1.02] active:scale-95 disabled:opacity-50 disabled:transform-none"
                >
                  Finalize & Submit Exam
                </button>
              </div>
            </div>
          </div>
        ) : (
          stats && (
            <ResultsDashboard 
              stats={stats} 
              details={mistakeDetails} 
              language={settings.language} 
              sourceText={passage}
              typedText={typedText}
              onRestart={resetExam} 
            />
          )
        )}
      </main>
    </div>
  );
};

