interface Props {
  stats: TypingStats;
  details: MistakeDetail[];
  language: Language;
  sourceText: string;
  typedText: string;
  onRestart: () => void;
}

const ResultsDashboard: React.FC<Props> = ({ stats, details, language, sourceText, typedText, onRestart }) => {
  const [view, setView] = useState<'compare' | 'table'>('compare');

  const exportPDF = () => {
    const doc = new jsPDF();
    doc.setFontSize(22);
    doc.setTextColor(63, 70, 229); // Indigo
    doc.text('Typing Performance Report', 20, 20);

    doc.setFontSize(12);
    doc.setTextColor(100);
    doc.text(`Language: ${language}`, 20, 35);
    doc.text(`Time Elapsed: ${Math.floor(stats.timeElapsed / 60)}m ${stats.timeElapsed % 60}s`, 20, 42);

    doc.setFontSize(14);
    doc.setTextColor(0);
    doc.text('Key Metrics:', 20, 55);
    doc.text(`- Gross Speed: ${stats.grossWpm} WPM`, 25, 65);
    doc.text(`- Net Speed: ${stats.netWpm} WPM`, 25, 75);
    doc.text(`- Accuracy: ${stats.accuracy}%`, 25, 85);
    doc.text(`- Total Strokes: ${stats.totalStrokes}`, 25, 95);
    doc.text(`- Mistakes (Full/Half): ${stats.fullMistakes} / ${stats.halfMistakes}`, 25, 105);

    doc.save('exam-result.pdf');
  };

  const sourceWords = sourceText.trim().split(/\s+/);
  const typedWords = typedText.trim().split(/\s+/);

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 max-w-6xl mx-auto pb-20">
      {/* Metrics Grid */}
      <div className="grid grid-cols-1 md:grid-cols-5 gap-4">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-indigo-50 text-center">
          <p className="text-gray-400 text-[10px] font-bold uppercase tracking-widest mb-1">Gross WPM</p>
          <p className="text-4xl font-black text-gray-800">{stats.grossWpm}</p>
