                    {sourceWords.map((word, i) => {
                      const isWrong = typedWords[i] !== undefined && typedWords[i] !== word;
                      const isMissing = typedWords[i] === undefined;
                      return (
                        <span key={i} className={`mr-1.5 inline-block ${isWrong ? 'bg-red-100 text-red-700 rounded px-0.5' : isMissing ? 'opacity-30' : ''}`}>
                          {word}
