                          {word}
                        </span>
                      );
                    })}
                  </div>
                </div>
              </div>

              {/* Legend */}
              <div className="flex flex-wrap gap-6 p-4 bg-gray-50 rounded-2xl border border-gray-100 text-xs font-bold text-gray-500">
                <div className="flex items-center gap-2">
