                </div>
                <div className="flex items-center gap-2">
                   <div className="w-3 h-3 bg-gray-300 rounded-full" /> <span>Omitted Word</span>
                </div>
                <div className="flex items-center gap-2">
                   <div className="w-3 h-3 bg-purple-500 rounded-full" /> <span>Extra Word Typed</span>
                </div>
              </div>
            </div>
          ) : (
            <div className="overflow-hidden border rounded-2xl">
              <table className="w-full text-left">
                <thead className="bg-gray-50 text-[10px] font-black text-gray-400 uppercase tracking-widest">
                  <tr>
                    <th className="px-8 py-4">Error Type</th>
                    <th className="px-8 py-4">Status</th>
                    <th className="px-8 py-4">Expected Word</th>
                    <th className="px-8 py-4">Your Typing</th>
