                        </td>
                        <td className="px-8 py-5 font-mono text-gray-400">{m.expected}</td>
                        <td className="px-8 py-5 font-mono text-red-600 font-bold">{m.typed}</td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

