import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  Language, 
  BackspaceMode, 
  ExamSettings, 
  TypingStats, 
  MistakeDetail 
} from './types';
import { PASSAGES, KRUTIDEV_MAP } from './constants';
import { calculateStats, calculateMistakes } from './utils/calculations';
import SettingsPanel from './components/SettingsPanel';
import ResultsDashboard from './components/ResultsDashboard';
import { Keyboard, Play, Pause, RotateCcw, Layout, Clock, Activity, AlertCircle } from 'lucide-react';

const App: React.FC = () => {
  // State
  const [settings, setSettings] = useState<ExamSettings>({
    language: Language.ENGLISH,
    timerMinutes: 5,
    highlightEnabled: false, // Defaulting to False as requested
    backspaceMode: BackspaceMode.FULL,
    showStats: true,
    useCustomPassage: false,
    customPassage: "",
  });

  const [passage, setPassage] = useState('');
  const [typedText, setTypedText] = useState('');
  const [isActive, setIsActive] = useState(false);
  const [timeLeft, setTimeLeft] = useState(0);
  const [isFinished, setIsFinished] = useState(false);
  const [totalStrokes, setTotalStrokes] = useState(0);
  const [stats, setStats] = useState<TypingStats | null>(null);
  const [mistakeDetails, setMistakeDetails] = useState<MistakeDetail[]>([]);

  // Refs
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const timerRef = useRef<number | null>(null);

  // Initialize Exam
  useEffect(() => {
    let finalPassage = "";
    if (settings.useCustomPassage && settings.customPassage.trim()) {
      finalPassage = settings.customPassage.trim();
    } else {
      const langPassages = PASSAGES[settings.language];
      finalPassage = langPassages[Math.floor(Math.random() * langPassages.length)];
    }

    setPassage(finalPassage);
    setTimeLeft(settings.timerMinutes * 60);
    resetExam();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [settings.language, settings.timerMinutes, settings.useCustomPassage, settings.customPassage]);

  const resetExam = () => {
    setIsActive(false);
    setIsFinished(false);
    setTypedText('');
    setTotalStrokes(0);
    setStats(null);
    setMistakeDetails([]);
    setTimeLeft(settings.timerMinutes * 60);
    if (timerRef.current) clearInterval(timerRef.current);
  };

  const finishExam = useCallback(() => {
    setIsActive(false);
    setIsFinished(true);
    if (timerRef.current) clearInterval(timerRef.current);

    const timeUsed = (settings.timerMinutes * 60) - timeLeft;
    const finalStats = calculateStats(
      passage,
      typedText,
      timeUsed,
      totalStrokes
    );
    const { details } = calculateMistakes(passage, typedText);

    setStats(finalStats);
    setMistakeDetails(details);
  }, [passage, typedText, timeLeft, totalStrokes, settings.timerMinutes]);

  // Timer Logic
  useEffect(() => {
    if (isActive && timeLeft > 0) {
      timerRef.current = window.setInterval(() => {
        setTimeLeft((prev) => prev - 1);
      }, 1000);
    } else if (timeLeft === 0 && isActive) {
      finishExam();
    }
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [isActive, timeLeft, finishExam]);

  // Handle Input
  const handleInputChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    if (isFinished) return;
    if (!isActive) {
      setIsActive(true);
    }

    let val = e.target.value;

    // Krutidev Mapping Logic
    if (settings.language === Language.HINDI_KRUTIDEV) {
      const lastChar = val.slice(-1);
      if (KRUTIDEV_MAP[lastChar]) {
        val = val.slice(0, -1) + KRUTIDEV_MAP[lastChar];
      }
    }

    setTypedText(val);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (isFinished) return;

    // Security: No Paste
    if (e.ctrlKey && (e.key === 'v' || e.key === 'V')) {
      e.preventDefault();
      return;
    }

    // Backspace Logic
    if (e.key === 'Backspace') {
      if (settings.backspaceMode === BackspaceMode.NO_BACKSPACE) {
        e.preventDefault();
        return;
      }
      if (settings.backspaceMode === BackspaceMode.LIMITED) {
        // Prevent backspacing across words
        if (typedText.endsWith(' ') || typedText.length === 0) {
          e.preventDefault();
          return;
        }
      }
    }

    // Track Strokes: Keys that contribute to characters/spaces
    if (e.key.length === 1 || e.key === 'Enter') {
      setTotalStrokes((prev) => prev + 1);
    }
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  // Rendering passage with highlights
  const renderPassage = () => {
    const sourceWords = passage.trim().split(/\s+/);
    const typedWords = typedText.trim().split(/\s+/);
    const currentWordIndex = typedWords.length - 1;

    return (
      <div 
        className={`text-xl leading-[1.8] p-8 h-72 overflow-y-auto no-select font-serif ${
          settings.language === Language.HINDI_KRUTIDEV ? 'font-krutidev' : 
          settings.language === Language.HINDI_MANGAL ? 'font-mangal' : ''
        }`}
      >
        {sourceWords.map((word, idx) => {
          let className = "mx-1 inline-block transition-colors ";

          if (settings.highlightEnabled) {
            if (idx === currentWordIndex && isActive) {
              className += "bg-yellow-100 rounded px-1 ";
            }
            if (idx < currentWordIndex) {
              className += typedWords[idx] === word ? "text-green-600 " : "text-red-500 underline decoration-2 ";
            }
          }

          return <span key={idx} className={className}>{word}</span>;
        })}
      </div>
    );
  };

  return (
    <div className="min-h-screen pb-20 bg-[#fafafa]">
      {/* Header */}
      <header className="bg-white border-b sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="bg-indigo-600 p-2.5 rounded-xl shadow-lg shadow-indigo-100">
              <Keyboard className="text-white w-7 h-7" />
            </div>
            <div>
              <h1 className="text-2xl font-black tracking-tight text-gray-900 leading-none">TypoGov</h1>
              <p className="text-[10px] text-indigo-500 font-black uppercase mt-1.5 tracking-widest">Govt-Grade Evaluation</p>
            </div>
          </div>

          <div className="flex items-center gap-6">
            <div className={`flex items-center gap-3 px-5 py-2.5 rounded-2xl border transition-all ${timeLeft < 60 ? 'bg-red-50 border-red-200 text-red-600' : 'bg-gray-50 border-gray-100'}`}>
              <Clock className="w-5 h-5" />
              <span className="font-mono font-black text-xl">{formatTime(timeLeft)}</span>
            </div>

            {!isFinished && (
              <div className="flex gap-3">
                <button
                  onClick={() => setIsActive(!isActive)}
                  className={`flex items-center gap-2 px-7 py-2.5 rounded-2xl font-black transition-all transform active:scale-95 shadow-xl ${
                    isActive 
                      ? 'bg-amber-100 text-amber-700 shadow-amber-50' 
                      : 'bg-indigo-600 text-white shadow-indigo-100 hover:bg-indigo-700'
                  }`}
                >
                  {isActive ? <><Pause className="w-5 h-5" /> Pause</> : <><Play className="w-5 h-5" /> Begin Test</>}
                </button>
                <button
                  onClick={resetExam}
                  className="p-3 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-2xl transition-all border border-gray-100 bg-white shadow-sm"
                  title="Reset Exam"
                >
                  <RotateCcw className="w-6 h-6" />
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-6 mt-10">
        {!isFinished ? (
          <div className="grid grid-cols-1 lg:grid-cols-4 gap-10">
            <div className="lg:col-span-1">
              <SettingsPanel 
                settings={settings} 
                setSettings={setSettings} 
                disabled={isActive} 
              />

              {settings.showStats && (
                <div className="mt-8 bg-white border border-gray-100 rounded-3xl p-8 shadow-sm">
                  <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em] mb-6 flex items-center gap-2">
                    <Activity className="w-4 h-4" /> Live Performance
                  </h3>
                  <div className="space-y-6">
                    <div className="flex justify-between items-end">
                      <span className="text-xs font-bold text-gray-500 uppercase">Strokes</span>
                      <span className="text-3xl font-black font-mono text-indigo-600">{totalStrokes}</span>
                    </div>
                    <div className="w-full bg-gray-100 h-1.5 rounded-full overflow-hidden">
                       <div className="bg-indigo-600 h-full transition-all duration-300 shadow-[0_0_8px_rgba(79,70,229,0.4)]" style={{ width: `${Math.min(100, (totalStrokes/passage.length)*100)}%` }} />
                    </div>
                    <div className="flex justify-between items-end pt-4 border-t border-gray-50">
                      <span className="text-xs font-bold text-gray-500 uppercase">Est. Words</span>
                      <span className="text-3xl font-black font-mono text-gray-800">{Math.floor(totalStrokes / 5)}</span>
                    </div>
                  </div>
                </div>
              )}
            </div>

            <div className="lg:col-span-3 space-y-8">
              <div className="bg-white border border-gray-100 rounded-[2.5rem] shadow-xl overflow-hidden flex flex-col">
                <div className="bg-indigo-50/30 px-8 py-4 border-b border-indigo-50/50 flex items-center justify-between">
                  <span className="text-[10px] font-black text-indigo-500 uppercase flex items-center gap-3 tracking-[0.2em]">
                    <Layout className="w-4 h-4" /> Exam Paper
                  </span>
                  <div className="flex gap-3">
                     <span className="px-3 py-1 bg-white border border-indigo-100 text-indigo-600 rounded-lg text-[10px] font-black uppercase shadow-sm">
                        {settings.language}
                     </span>
                  </div>
                </div>
                {renderPassage()}
              </div>

              <div className="relative group">
                <textarea
                  ref={inputRef}
                  disabled={!isActive && !isFinished}
                  value={typedText}
                  onChange={handleInputChange}
                  onKeyDown={handleKeyDown}
                  onContextMenu={(e) => e.preventDefault()}
                  onPaste={(e) => e.preventDefault()}
                  placeholder={isActive ? "Match the text above as quickly and accurately as possible..." : "Click 'Begin Test' above to start your exam session."}
                  className={`w-full h-80 p-10 text-xl leading-relaxed rounded-[2.5rem] border-2 transition-all outline-none resize-none shadow-xl ${
                    !isActive ? 'bg-gray-100/50 border-transparent opacity-60 cursor-not-allowed' : 'bg-white border-indigo-500 ring-8 ring-indigo-50 shadow-indigo-100'
                  } ${
                    settings.language === Language.HINDI_KRUTIDEV ? 'font-krutidev' : 
                    settings.language === Language.HINDI_MANGAL ? 'font-mangal' : ''
                  }`}
                  spellCheck={false}
                  autoComplete="off"
                  autoCorrect="off"
                  autoCapitalize="off"
                />
                {!isActive && !isFinished && (
                  <div className="absolute inset-0 flex items-center justify-center rounded-[2.5rem]">
                     <div className="bg-white/80 backdrop-blur-md px-10 py-6 rounded-3xl border border-white shadow-2xl flex flex-col items-center gap-4">
                        <Play className="w-10 h-10 text-indigo-600 fill-indigo-600" />
                        <p className="font-black text-gray-900 tracking-tight">Ready for your examination?</p>
                     </div>
                  </div>
                )}
              </div>

              {/* Instructions Bar */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="flex items-start gap-4 p-6 bg-white border border-gray-100 rounded-3xl shadow-sm">
                  <div className="p-2 bg-indigo-50 rounded-xl">
                    <Activity className="w-6 h-6 text-indigo-500" />
                  </div>
                  <div>
                    <h4 className="font-black text-gray-900 text-[10px] uppercase tracking-widest">Logic: Strokes/5</h4>
                    <p className="text-xs text-gray-400 mt-2 leading-relaxed">
                      Speed is calculated as standard words per minute. Every 5 keypresses count as 1 word.
                    </p>
                  </div>
                </div>
                <div className="flex items-start gap-4 p-6 bg-white border border-gray-100 rounded-3xl shadow-sm">
                  <div className="p-2 bg-red-50 rounded-xl">
                    <ShieldAlert className="w-6 h-6 text-red-500" />
                  </div>
                  <div>
                    <h4 className="font-black text-gray-900 text-[10px] uppercase tracking-widest">Mistake Penalty</h4>
                    <p className="text-xs text-gray-400 mt-2 leading-relaxed">
                      Full mistakes (substitution/omission) reduce your word count. Half mistakes (caps) reduce by 0.5 words.
                    </p>
                  </div>
                </div>
              </div>

              <div className="flex justify-center pt-6">
                <button
                  onClick={finishExam}
                  disabled={!isActive}
                  className="bg-gray-900 text-white px-16 py-5 rounded-2xl font-black text-lg shadow-2xl shadow-gray-200 hover:bg-black transition-all transform hover:-translate-y-1 active:translate-y-0 disabled:opacity-30 disabled:transform-none"
                >
                  Submit Final Examination
                </button>
              </div>
            </div>
          </div>
        ) : (
          stats && (
            <ResultsDashboard 
              stats={stats} 
              details={mistakeDetails} 
              language={settings.language} 
              sourceText={passage}
              typedText={typedText}
              onRestart={resetExam} 
            />
          )
        )}
      </main>

      <footer className="mt-20 border-t border-gray-100 py-12 text-center text-[10px] font-bold text-gray-400 uppercase tracking-[0.4em]">
        TypoGov Evaluation Engine v2.5 • Unified Performance Analytics
      </footer>
    </div>
  );
};

